async function getWeaponsToReload(actor) {
    weapons = actor.items.filter(i => i.type === "weapon" && i.system.equipped && i.system.properties.rel && i.system.consume.type === "ammo");
    weaponCapacities = []
    weapons.forEach(w => {
        if (!w.system.consume.target) {
            weaponCapacities.push({"id": w.id, "name": w.name, "ammo": 0, "capacity": w.flags.cyberpunk5e.reload});
            return;
        }
        ammo = actor.items.find(i => i.id === w.system.consume.target);
        if (!ammo) {
            weaponCapacities.push({"id": w.id, "name": w.name, "ammo": 0, "capacity": w.flags.cyberpunk5e.reload});
        } else {
            weaponCapacities.push({"id": w.id, "name": w.name, "ammo": ammo.system.quantity || 0, "capacity": w.flags.cyberpunk5e.reload});
        }
    });
    return weaponCapacities.filter(wc => {
        return wc.ammo < wc.capacity;
    });
}

function getTotalAmmoQuantity(items, ammoType) {
    return items.filter(i => {
        if (!i.system.equipped) return false;
        if (!i.flags.cyberpunk5e) return false;
        // if (!i.flags.cyberpunk5e.type !== 'container') return false;
        if (!i.flags.cyberpunk5e.capacity) return false;
        return i.flags.cyberpunk5e.ammo_type === ammoType
    }).map(i => {
        var ammoItem = items.find(it => it.id === i.system.consume.target);
        return ammoItem ? ammoItem.system.quantity : 0;
    }).reduce((r, opt) => r + opt, 0)
}

function getAmmoQuantityToReload(items, weapon) {
    var weaponStats = selectedWeapon.flags.cyberpunk5e;
    var totalQty = getTotalAmmoQuantity(items, weaponStats.ammo_type);

    var weaponAmmoItem = items.find(i => i.id === weapon.system.consume.target);
    if (weaponAmmoItem) {
        return Math.min(weaponStats.reload - weaponAmmoItem.system.quantity, totalQty);
    } else {
        return Math.min(weaponStats.reload, totalQty);
    }
}

async function reloadButton(html, token) {
    let selectedWeaponId = html.find("[id=weapons]")[0].value;
    if (!selectedWeaponId) {
        console.log("No weapon selected!")
        return;
    }
    selectedWeapon = token.actor.items.find(i => i.id === selectedWeaponId)
    if (!selectedWeapon) {
        console.error("Could not find weapon with selected token!")
        return;
    }

    // Check equipped ammo boxes to see how much ammo you can fill
    var ammoQty = Math.max(getAmmoQuantityToReload(token.actor.items, selectedWeapon), 0)

    // If no ammo target exists, create it.
    targetAmmoId = selectedWeapon.system.consume.target;
    targetAmmo = targetAmmoId ? token.actor.items.find(i => i.id === targetAmmoId) : null;
    if (!targetAmmo) {
        targetAmmo = await createAmmo(token.actor, selectedWeapon, ammoQty)
        await selectedWeapon.update({"system.consume.target": targetAmmo.id})
    } else {
        weaponStats = selectedWeapon.flags.cyberpunk5e;
        if (!weaponStats) return;
        await targetAmmo.update({"system.quantity": targetAmmo.system.quantity + ammoQty})
    }

    // Remove ammoQty from ammo boxes
    await removeAmmoQtyFromAmmoBoxes(token.actor.items, selectedWeapon.flags.cyberpunk5e.ammo_type, ammoQty);

    // Output the reload to chat.
    let content_html = `${token.actor.name} has reloaded ${selectedWeapon.name}!`;
    ChatMessage.create({content: content_html});
}

async function removeAmmoQtyFromAmmoBoxes(items, ammoType, ammoQty) {
    var qtyToRemove = ammoQty
    var ammoTargets = items.filter(i => {
        if (!i.system.equipped) return false;
        if (!i.flags.cyberpunk5e) return false;
        // if (!i.flags.cyberpunk5e.type !== 'container') return false;
        if (!i.flags.cyberpunk5e.capacity) return false;
        if (i.flags.cyberpunk5e.ammo_type !== ammoType) return false;
        return true;
    }).map(a => {
        return items.find(i => a.system.consume.target === i.id)
    }).filter(a => {
        if (!a) return false;
        else return true;
    }).sort((a, b) => {
        return a.system.quantity < b.system.quantity
    });

    for (const ammoTarget of ammoTargets) {
        if (qtyToRemove <= 0) return;
        var ammoBoxQty = ammoTarget.system.quantity;
        var qtyRemoved = Math.min(qtyToRemove, ammoBoxQty);
        await ammoTarget.update({'system.quantity': ammoBoxQty - qtyRemoved})
        qtyToRemove -= qtyRemoved;
    };
}

async function createAmmo(actor, weapon, ammoQty) {
    weaponStats = weapon.flags.cyberpunk5e
    weaponName = weapon.name.includes('[') ? weapon.name.substring(0, weapon.name.lastIndexOf('[')).trim() : weapon.name;
    if (!weaponStats) return null;
    ammoType = weaponStats.ammo_type
    ammoName = ammoType[0].toUpperCase() + ammoType.slice(1)
    ammoItem = ammoData[ammoType]
    ammoItem.name = ammoName.concat(" [" + weaponName + "]")
    ammoItem.system.quantity = ammoQty
    items = await actor.createEmbeddedDocuments('Item', [ammoItem])
    return items[0]
}

function updateAvailableLabel(html, items) {
    label = html.find('[id="availableLabel"]')[0];
    selectedWeaponId = html.find("[id=weapons]")[0].value;
    if (!selectedWeaponId) {
        label.innerHTML = '<p />';
        return;
    }
    selectedWeapon = items.find(i => i.id === selectedWeaponId);
    totalQty = getTotalAmmoQuantity(items, selectedWeapon.flags.cyberpunk5e.ammo_type)

    label.innerHTML = `<p>${totalQty} ${selectedWeapon.flags.cyberpunk5e.ammo_type} available</p>`
}

async function addUpdateHandlers(html, actor) {
    html.find('[id="weapons"]').on("change", function(){updateAvailableLabel(html, actor.items)});
}

